-- 0028 — the three services the shelf opens with.
--
-- Business registration, a birth certificate and a passport application: the
-- three people actually walk into a shop and ask for, with the forms the
-- Registrar-General, the Births and Deaths Registry and the Passport Office
-- each want. They are seeded rather than documented because a module that
-- opens empty is a module somebody has to design before they can use it, and
-- what these three ask for is not a matter of opinion.
--
-- Seeded once, and only into an empty catalogue, so an admin who deletes one
-- does not find it back after the next deploy. Everything about them is
-- ordinary data: the prices below are placeholders to be set from the console,
-- and every field, variant and speed option can be edited, suspended or
-- deleted from Admin -> Data bundles -> Products.

DO $$
BEGIN
IF NOT EXISTS (SELECT 1 FROM "DataService") THEN

-- Business registration
INSERT INTO "DataService" ("id","slug","name","tagline","summary","icon","accentFrom","accentTo","fields","terms","isActive","onStore","order") VALUES (
  'svc_business_registration', 'business-registration', 'Business registration', 'Registrar-General filing, handled end to end', 'We prepare and file your registration with the Office of the Registrar of Companies and deliver your certificate. Pick the kind of entity, fill in the details once, and we take it from there.', '🏢', '#1d4ed8', '#3b82f6', '[{"key": "applicant_name", "label": "Applicant full name", "type": "text", "required": true, "hint": "As it appears on the Ghana Card", "options": [], "half": true}, {"key": "applicant_phone", "label": "Phone number", "type": "phone", "required": true, "hint": "", "options": [], "half": true}, {"key": "applicant_email", "label": "Email address", "type": "email", "required": false, "hint": "", "options": [], "half": true}, {"key": "ghana_card_number", "label": "Ghana Card number", "type": "text", "required": true, "hint": "GHA-123456789-0", "options": [], "half": true}, {"key": "date_of_birth", "label": "Date of birth", "type": "date", "required": false, "hint": "", "options": [], "half": true}, {"key": "occupation", "label": "Occupation", "type": "text", "required": false, "hint": "", "options": [], "half": true}, {"key": "residential_address", "label": "Residential address", "type": "text", "required": true, "hint": "", "options": [], "half": false}, {"key": "business_name_1", "label": "Proposed business name — first choice", "type": "text", "required": true, "hint": "", "options": [], "half": true}, {"key": "business_name_2", "label": "Proposed business name — second choice", "type": "text", "required": false, "hint": "", "options": [], "half": true}, {"key": "nature_of_business", "label": "Nature of business", "type": "textarea", "required": true, "hint": "What the business will do, in a sentence or two", "options": [], "half": false}, {"key": "business_address", "label": "Business address", "type": "text", "required": true, "hint": "", "options": [], "half": false}, {"key": "digital_address", "label": "Ghana Post GPS address", "type": "text", "required": false, "hint": "e.g. GA-123-4567", "options": [], "half": true}, {"key": "tin_number", "label": "TIN (if you have one)", "type": "text", "required": false, "hint": "", "options": [], "half": true}, {"key": "id_front", "label": "Ghana Card — front", "type": "file", "required": true, "hint": "", "options": [], "half": false}, {"key": "id_back", "label": "Ghana Card — back", "type": "file", "required": true, "hint": "", "options": [], "half": false}, {"key": "passport_photo", "label": "Passport photograph", "type": "file", "required": true, "hint": "", "options": [], "half": false}]', 'Registration fees cover Nickimart''s filing service and the statutory charges in force on the day of filing.
Names are subject to availability at the Registrar-General''s Department. Where a first choice is unavailable we file the second.
Turnaround runs from the day every required document is received, not from the day of payment.
Statutory fee increases announced after payment are billed separately before filing.
Fees are non-refundable once a filing has been submitted.', true, true, 1
);
