-- Birth certificate
INSERT INTO "DataService" ("id","slug","name","tagline","summary","icon","accentFrom","accentTo","fields","terms","isActive","onStore","order") VALUES (
  'svc_birth_certificate', 'birth-certificate', 'Birth certificate', 'Births & Deaths Registry filing and collection', 'New registrations, late registrations and certified copies, filed at the Births and Deaths Registry and delivered to you.', '📜', '#047857', '#10b981', '[{"key": "child_name", "label": "Full name on the certificate", "type": "text", "required": true, "hint": "", "options": [], "half": false}, {"key": "date_of_birth", "label": "Date of birth", "type": "date", "required": true, "hint": "", "options": [], "half": true}, {"key": "place_of_birth", "label": "Place of birth", "type": "text", "required": true, "hint": "Hospital or town", "options": [], "half": true}, {"key": "sex", "label": "Sex", "type": "select", "required": true, "hint": "", "options": ["Male", "Female"], "half": true}, {"key": "mother_name", "label": "Mother''s full name", "type": "text", "required": true, "hint": "", "options": [], "half": true}, {"key": "mother_nationality", "label": "Mother''s nationality", "type": "text", "required": false, "hint": "", "options": [], "half": true}, {"key": "father_name", "label": "Father''s full name", "type": "text", "required": false, "hint": "", "options": [], "half": true}, {"key": "father_nationality", "label": "Father''s nationality", "type": "text", "required": false, "hint": "", "options": [], "half": true}, {"key": "applicant_name", "label": "Applicant''s full name", "type": "text", "required": true, "hint": "", "options": [], "half": true}, {"key": "applicant_phone", "label": "Phone number", "type": "phone", "required": true, "hint": "", "options": [], "half": true}, {"key": "relationship", "label": "Relationship to the person named", "type": "text", "required": false, "hint": "Parent, guardian, self", "options": [], "half": true}, {"key": "delivery_address", "label": "Delivery address", "type": "text", "required": true, "hint": "", "options": [], "half": false}, {"key": "hospital_record", "label": "Weighing card or hospital record", "type": "file", "required": false, "hint": "", "options": [], "half": false}, {"key": "applicant_id", "label": "Applicant''s Ghana Card", "type": "file", "required": true, "hint": "", "options": [], "half": false}]', 'Details must match the hospital or weighing-card record exactly; the Registry rejects applications that do not.
A late registration requires supporting evidence of the birth and may be referred for further checks.
Turnaround runs from the day every required document is received.
Fees cover Nickimart''s filing service and the Registry''s statutory charges.
Fees are non-refundable once an application has been submitted.', true, true, 2
);
