-- Passport application
INSERT INTO "DataService" ("id","slug","name","tagline","summary","icon","accentFrom","accentTo","fields","terms","isActive","onStore","order") VALUES (
  'svc_passport_application', 'passport-application', 'Passport application', 'Ghanaian passport applications and renewals', 'We complete the application, book the biometric appointment and follow it through to collection. You attend the appointment in person; we do everything either side of it.', '🛂', '#b45309', '#f59e0b', '[{"key": "full_name", "label": "Full name (as on the Ghana Card)", "type": "text", "required": true, "hint": "", "options": [], "half": false}, {"key": "date_of_birth", "label": "Date of birth", "type": "date", "required": true, "hint": "", "options": [], "half": true}, {"key": "place_of_birth", "label": "Place of birth", "type": "text", "required": true, "hint": "", "options": [], "half": true}, {"key": "sex", "label": "Sex", "type": "select", "required": true, "hint": "", "options": ["Male", "Female"], "half": true}, {"key": "ghana_card_number", "label": "Ghana Card number", "type": "text", "required": true, "hint": "", "options": [], "half": true}, {"key": "phone", "label": "Phone number", "type": "phone", "required": true, "hint": "", "options": [], "half": true}, {"key": "email", "label": "Email address", "type": "email", "required": false, "hint": "", "options": [], "half": true}, {"key": "occupation", "label": "Occupation", "type": "text", "required": false, "hint": "", "options": [], "half": true}, {"key": "height", "label": "Height (cm)", "type": "number", "required": false, "hint": "", "options": [], "half": true}, {"key": "residential_address", "label": "Residential address", "type": "text", "required": true, "hint": "", "options": [], "half": false}, {"key": "centre", "label": "Preferred processing centre", "type": "select", "required": true, "hint": "", "options": ["Accra", "Kumasi", "Takoradi", "Tamale", "Ho", "Sunyani"], "half": true}, {"key": "kin_name", "label": "Next of kin", "type": "text", "required": true, "hint": "", "options": [], "half": true}, {"key": "kin_phone", "label": "Next of kin phone", "type": "phone", "required": true, "hint": "", "options": [], "half": true}, {"key": "id_front", "label": "Ghana Card — front", "type": "file", "required": true, "hint": "", "options": [], "half": false}, {"key": "id_back", "label": "Ghana Card — back", "type": "file", "required": true, "hint": "", "options": [], "half": false}, {"key": "birth_certificate", "label": "Birth certificate", "type": "file", "required": false, "hint": "", "options": [], "half": false}, {"key": "passport_photo", "label": "Passport photograph", "type": "file", "required": true, "hint": "", "options": [], "half": false}]', 'The applicant must attend the biometric appointment in person; this cannot be done on your behalf.
Details must match the Ghana Card exactly. A mismatch is the single most common cause of rejection.
Fees cover Nickimart''s service and the Passport Office''s statutory charges.
Appointment dates are set by the Passport Office and are outside Nickimart''s control.
Fees are non-refundable once an application has been lodged.', true, true, 3
);
